 "content": "def transform(grid):
    """Repeat the marked pattern tile across regions separated by a cross."""
    h, w = len(grid), len(grid[0])
    # The separator color is the most frequent non-background line color:
    # find a complete horizontal and vertical line of the same color.
    separator = None
    for r, row in enumerate(grid):
        colors = set(row)
        for color in colors:
            if all(x == color for x in row):
                separator = color
                sep_row = r
                break
        if separator is not None:
            break
    for c in range(w):
        color = grid[0][c]
        if all(grid[r][c] == color for r in range(h)):
            if separator is None or color == separator:
                separator = color
                sep_col = c
                break
    # The source pattern is the upper-left region; copy it into every region.
    top = sep_row if 'sep_row' in locals() else h
    left = sep_col if 'sep_col' in locals() else w
    tile = [row[:left] for row in grid[:top]]
    out = [row[:] for row in grid]
    for r0 in range(0, h, top + 1):
        for c0 in range(0, w, left + 1):
            if r0 == 0 and c0 == 0:
                continue
            for dr in range(top):
                for dc in range(left):
                    if r0 + dr < h and c0 + dc < w:
                        out[r0 + dr][c0 + dc] = tile[dr][dc]
    return out
