    vlines = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    # A repeated set of divider lines has a sample tile between the first pair.
    # For a single divider, the sample is the upper/left tile.
    if len(vlines) >= 2:
        cstart, cend = vlines[0] + 1, vlines[1]
    elif vlines:
        cstart, cend = 0, vlines[0]
    else:
        cstart, cend = 0, w
    if len(hlines) >= 2:
        rstart, rend = hlines[0] + 1, hlines[1]
    elif hlines:
        rstart, rend = 0, hlines[0]
    else:
        rstart, rend = 0, h

    tile = [row[cstart:cend] for row in grid[rstart:rend]]
    th, tw = len(tile), len(tile[0])
    out = [row[:] for row in grid]

    def tile_index(pos, dividers, size):
        # Restart the pattern after each separator line.
        start = 0
        for divider in dividers:
            if pos < divider:
                break
            start = divider + 1
        return (pos - start) % size

    for r in range(h):
        if r in hlines:
            continue
        for c in range(w):
            if c in vlines:
                continue
            ri = tile_index(r, hlines, th) if hlines else r % th
            ci = tile_index(c, vlines, tw) if vlines else c % tw
            out[r][c] = tile[ri][ci]
    return out
